fn mark_failed(db, sentry, row_id, reason) -> RowOutcome {
  case uuid.from_string(row_id) {
    Ok(row_uuid) -> { let _ = sql.sweep_mark_failed(db, row_uuid, reason); Nil }
    Error(_) -> Nil
  }
  capture(sentry, row_id, reason, "processing error")
  Failed
}

